package com.system.recovery.service;
import com.system.recovery.model.*; import com.system.recovery.repository.*; import com.system.recovery.dto.*; import io.micrometer.core.instrument.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class RecoveryOrchestrator { private final ApprovalRequestRepository approvals; private final RecoveryAuditRepository audits; private final MeterRegistry metrics; public RecoveryOrchestrator(ApprovalRequestRepository a,RecoveryAuditRepository u,MeterRegistry m){approvals=a;audits=u;metrics=m;}
 public String handle(RecoveryDecisionService.DecisionResult r){ RecoveryDecision d=r.decision(); metrics.counter("business_recovery_attempts_total","action",d.action().name()).increment(); if(d.requiresHumanApproval()){ ApprovalRequest q=approvals.save(new ApprovalRequest(r.signalBundle().orderId(),d.action(),d.toString())); audits.save(new RecoveryAudit(r.signalBundle().orderId(),r.signalBundle().toString(),d.toString(),"PENDING_APPROVAL:"+q.getId())); return "PENDING_APPROVAL";} audits.save(new RecoveryAudit(r.signalBundle().orderId(),r.signalBundle().toString(),d.toString(),"EXECUTED:"+d.action())); return "EXECUTED"; }
 public List<ApprovalRequest> pending(){return approvals.findByStatus("PENDING");} public ApprovalRequest resolve(UUID id,boolean approve){ApprovalRequest q=approvals.findById(id).orElseThrow();q.setStatus(approve?"APPROVED":"REJECTED");approvals.save(q); audits.save(new RecoveryAudit(q.getOrderId(),"approval",q.getDecisionJson(),q.getStatus())); if(!approve)metrics.counter("business_recovery_false_positive_total").increment(); return q;}}
